"""C# language-native contracts; no Unity or ASP.NET dependency."""
from build import S, lesson as L


def lessons():
 return [
 L('toolchain','SDK projects and top-level programs','The .NET SDK builds projects described by a csproj file. dotnet run builds and launches a project; dotnet build does not launch it. Top-level statements provide an implicit entry point. using imports namespaces, not downloaded packages.',
 S('$ dotnet ~new console~','Creates a console project','Runs an existing application|Publishes to a server','The console template creates a project and starter source.','run|build','What does this command do?'),
 S('$ dotnet ~build~','Builds the project without running it','Runs the application|Creates a test result','build produces assemblies and reports compiler diagnostics.','run|new console','What action is requested?'),
 S('~using~ System;\nConsole.WriteLine("${word}");','Imports the System namespace','Installs a package|Creates a System object','This using directive shortens type names in source.','namespace|import','What does the first line do?'),
 S('Console.~WriteLine~("${word}");','${word}','No output|Compile error','A top-level statement can write a line without an explicit Main declaration.','ReadLine|Clear')),
 L('values','Static types, inference, and arithmetic','var infers a static local type; it is distinct from dynamic. Value types such as int store values directly. Integer division truncates, decimal supports decimal arithmetic, and checked detects integral overflow. const requires a compile-time value.',
 S('var n=${n}; n++; Console.WriteLine(~n~);','${next}','${n}|0','Inference chooses int and increment updates that integer.','n-1|0'),
 S('Console.WriteLine(${n} ~/~ ${m});','${div}','${mul}|${add}','Integer operands produce an integer quotient.','*|+'),
 S('decimal price=~1.5m~; Console.WriteLine(price==1.5m);','True','False|Compile error','The m suffix creates a decimal literal.','1.5|"1.5"'),
 S('int n=int.MaxValue; try {n=~checked(n+1)~;} catch(OverflowException){Console.WriteLine("overflow");}','overflow','-2147483648|Compile error','checked raises an exception when the addition exceeds int range.','unchecked(n+1)|n')),
 L('strings','Strings and interpolation','Strings are immutable UTF-16 sequences. == compares string contents, unlike object reference identity. Interpolation evaluates expressions; StringBuilder supports repeated mutation. Length counts UTF-16 code units rather than all user-perceived characters.',
 S('string name="${word}"; Console.WriteLine(~$"Hello {name}"~);','Hello ${word}','Hello {name}|Compile error','The dollar prefix enables interpolation.','"Hello {name}"|name'),
 S('string s="${word}"; s.ToUpperInvariant(); Console.WriteLine(~s~);','${word}','${upper}|Compile error','The conversion returns a new string; the ignored result changes no binding.','s.ToUpperInvariant()|s.Length'),
 S('Console.WriteLine("${word}".~Length~);','${length}','0|Compile error','Length is a property rather than a method.','Length()|Count()'),
 S('Console.WriteLine(new string("${word}".ToCharArray()) ~==~ "${word}");','True','False|Compile error','The string equality operator compares contents.','!=|is')),
 L('branches','Patterns and switch expressions','if needs bool. Switch expressions return a value and should cover possible inputs. Pattern matching combines shape checks and bindings. The discard pattern _ supplies a fallback; && short-circuits.',
 S('int n=${n}; Console.WriteLine(n ~>~ 0 ? "yes" : "no");','yes','no|Compile error','The positive integer selects yes.','<|=='),
 S('int n=0; bool ok=false ~&&~ (++n>0); Console.WriteLine(n);','0','1|Compile error','The right operand is skipped when the left is false.','&|||'),
 S('string label=${n} switch { > 0 ~=>~ "positive", _ => "other" }; Console.WriteLine(label);','positive','other|Compile error','A relational pattern matches the positive input.','->|:'),
 S('object x="${word}"; if(x ~is string text~) Console.WriteLine(text.Length);','${length}','0|Compile error','The type pattern introduces a string variable in the successful branch.','as string text|is int text')),
 L('iteration','Arrays and foreach','Arrays have fixed length. foreach over value elements gives values, not writable aliases. for supports indexed mutation; continue skips an iteration. Collections and arrays differ in API details such as Count versus Length.',
 S('int[] a={${n},${m}}; Console.WriteLine(a.~Length~);','2','1|Compile error','Array Length counts the elements.','Count|Size'),
 S('int[] a={${n}}; for(int i=0;i<a.Length;i++) a[i]++; Console.WriteLine(a[~0~]);','${next}','${n}|Compile error','The indexed assignment modifies the stored element.','1|2'),
 S('int total=0; foreach(int n in new[]{${n},${m}}) total+=n; Console.WriteLine(~total~);','${add}','${mul}|0','foreach visits both integer values.','total+1|0'),
 S('int n=0; for(int i=0;i<3;i++){if(i==1) ~continue~; n++;} Console.WriteLine(n);','2','1|3','The middle iteration is skipped.','break|return')),
 L('methods','Parameters, named arguments, and ref','Parameters pass values unless ref, out, or in specifies otherwise. Named arguments clarify call-site meaning; defaults supply omitted values. Local functions keep small helpers near their use. out is useful for Try-style parsing.',
 S('int Bump(int n)=>~n+1~; Console.WriteLine(Bump(${n}));','${next}','${n}|0','An expression-bodied function returns its expression.','n|0'),
 S('void Bump(~ref int n~){n++;} int n=${n}; Bump(ref n); Console.WriteLine(n);','${next}','${n}|Compile error','ref aliases the caller variable and must appear at both declaration and call.','int n|out int n'),
 S('int Size(int n=${n})=>n; Console.WriteLine(~Size()~);','${n}','0|Compile error','The omitted argument uses the declared default.','Size(0)|Size'),
 S('bool ok=int.TryParse("${n}",~out int n~); Console.WriteLine(n+1);','${next}','${n}|Compile error','TryParse writes the parsed result through an out argument.','ref int n|int n')),
 L('nullability','Nullable values and reference contracts','int? can contain an integer or null. Nullable reference annotations guide compiler analysis but do not add automatic runtime checks. ?. skips a member access for null; ?? supplies a fallback. The null-forgiving ! only suppresses a warning.',
 S('int? n=null; Console.WriteLine(n ~??~ ${n});','${n}','null|Compile error','The coalescing operator chooses the fallback when n is null.','|||&&'),
 S('string? name=null; Console.WriteLine(name~?.~Length ?? 0);','0','Throws NullReferenceException|Compile error','Conditional access returns null without calling Length.','.|::'),
 S('int? n=${n}; Console.WriteLine(n.~HasValue~);','True','False|Compile error','HasValue reports whether a nullable value contains an integer.','Value|GetType()'),
 S('string? text=null; try {Console.WriteLine(text~!~.Length);} catch(NullReferenceException){Console.WriteLine("null");}','null','0|Compile error','The null-forgiving operator does not make the dereference safe at runtime.','?|?? ""')),
 L('properties','Properties and object initialization','Properties expose controlled access while keeping field representation private. get and set may execute code. init permits initialization but restricts later assignment. Object initializers call setters or init accessors after construction.',
 S('// Type declaration:\nclass Counter {public int Value {get; ~private set;~}}','Outside code can read but cannot set Value','Value is static|Value is a compile-time constant','The setter has narrower visibility than the getter.','set;|init;','What API boundary is expressed?'),
 S('// Type declaration:\nclass Item {public string Name {get; ~init;~}="";}','Name can be assigned during initialization','Name can never be assigned|Name changes on every read','init allows object initialization but not ordinary later assignment.','set;|private set;','When may external code assign Name?'),
 S('var item=new Item {~Name~="${word}"}; Console.WriteLine(item.Name);\nclass Item {public string Name {get;set;}="";}','${word}','Empty string|Compile error','An object initializer assigns the property.','name|Value'),
 S('var item=new Item(${n}); Console.WriteLine(item.Double);\nclass Item(int n){public int Double ~=> n*2~;}','${double}','${n}|Compile error','An expression-bodied getter computes a value from captured constructor state.','=> n|=> 0')),
 L('semantics','Struct copies and class identity','Struct variables contain values; class variables hold object references. Copying a struct copies its fields, while copying a class reference aliases the object. A struct containing references still shares those referenced objects. Choose types according to intended identity and mutation.',
 S('var a=new Point{X=${n}}; var b=a; b.X=0; Console.WriteLine(~a.X~);\nstruct Point{public int X;}','${n}','0|Compile error','The struct assignment creates an independent copy of its int field.','b.X|0'),
 S('var a=new Box{X=${n}}; var b=a; b.X=0; Console.WriteLine(~a.X~);\nclass Box{public int X;}','0','${n}|Compile error','Both class references point to the same object.','a.X+1|1'),
 S('var a=new object(); var b=a; Console.WriteLine(~object.ReferenceEquals(a,b)~);','True','False|Compile error','ReferenceEquals checks whether the variables refer to the same object.','!object.ReferenceEquals(a,b)|a is null'),
 S('int n=${n}; object boxed=n; n++; Console.WriteLine(~boxed~);','${n}','${next}|Compile error','Boxing copies the current int into an object; later changes to n do not change it.','n|0')),
 L('interfaces','Interfaces and virtual dispatch','Interfaces describe capabilities. Classes explicitly implement them. virtual allows overriding and override supplies a derived implementation; hiding with new has different dispatch behavior. IDisposable expresses a deterministic cleanup contract.',
 S('ILabel x=new Item(); Console.WriteLine(x.Text());\ninterface ILabel{string Text();}\nclass Item ~: ILabel~ {public string Text()=>"${word}";}','${word}','Compile error|null','The colon declares interface implementation in C#.','implements ILabel|extends ILabel'),
 S('Base x=new Child(); Console.WriteLine(x.Text());\nclass Base{public virtual string Text()=>"base";}\nclass Child:Base{public ~override~ string Text()=>"${word}";}','${word}','base|Compile error','A virtual call dispatches to the runtime override.','new|static'),
 S('object x="${word}"; Console.WriteLine(x ~is~ string);','True','False|Compile error','is tests runtime compatibility without an unsafe cast.','as|=='),
 S('IDisposable r=new Resource(); r.~Dispose()~;\nclass Resource:IDisposable{public void Dispose(){Console.WriteLine("done");}}','done','No output|Compile error','The interface exposes the cleanup operation.','ToString()|GetHashCode()')),
 L('collections','Generic collection contracts','List<T> is mutable; arrays use Length while collections often expose Count. Dictionary.TryGetValue separates absence from default values. Generic parameters retain element type without manual object casts. Collection operations here teach APIs, not algorithms.',
 S('var a=new List<int>{${n}}; a.~Add~(${m}); Console.WriteLine(a.Count);','2','1|Compile error','Add appends an element to the mutable list.','Remove|Contains'),
 S('var m=new Dictionary<string,int>(); bool ok=m.~TryGetValue~("${word}",out int n); Console.WriteLine(ok);','False','True|Compile error','An absent key reports false and writes the value-type default.','Remove|ContainsKey'),
 S('var s=new HashSet<string>{"${word}","${word}"}; Console.WriteLine(s.~Count~);','1','2|Compile error','Equal values occupy one set entry.','Length|Capacity'),
 S('var a=new List<~string~>{"${word}"}; Console.WriteLine(a[0].Length);','${length}','0|Compile error','The generic argument ensures retrieved elements are strings.','int|object')),
 L('errors','Exceptions and filters','Exceptions propagate until a matching handler. Exception filters use when and leave unmatched failures for other handlers. finally handles unconditional cleanup. throw; preserves the current exception stack, unlike throwing a caught variable as a new throw site.',
 S('try {int.Parse("bad");} catch(~FormatException~){Console.WriteLine("invalid");}','invalid','bad|Compile error','Malformed numeric text causes FormatException.','IOException|NullReferenceException'),
 S('try {Console.WriteLine("${word}");} ~finally~ {Console.WriteLine("done");}','${word}\ndone','done|${word}','finally executes after the normal body.','else|catch'),
 S('try {throw new Exception("${word}");} catch(Exception e) ~when~ (e.Message=="${word}"){Console.WriteLine("matched");}','matched','Uncaught exception|Compile error','A true filter makes this catch applicable.','if|where'),
 S('// Inside catch(Exception e):\n~throw;~','Rethrows while preserving the original stack trace','Swallows the error|Returns the exception as a value','A bare throw rethrows the currently handled exception.','throw e;|return;','What does this statement do?')),
 L('resources','Using and disposal scope','using statements and declarations dispose IDisposable resources deterministically. A using declaration lasts to the end of its containing scope. await using supports asynchronous cleanup. File APIs can throw; memory reclamation does not replace resource management.',
 S('~using~ (var r=new System.IO.StringReader("${word}")){Console.WriteLine(r.ReadToEnd());}','${word}','No output|Compile error','The reader is disposed after leaving the using block.','lock|if'),
 S('{~using~ var r=new Resource(); Console.WriteLine("${word}");}\nclass Resource:IDisposable{public void Dispose(){Console.WriteLine("closed");}}','${word}\nclosed','closed\n${word}|${word}','A using declaration disposes the resource at the block end.','var|await', 'What is the output?'),
 S('Console.WriteLine(System.IO.Path.~GetFileName~("folder/${word}.txt"));','${word}.txt','folder|Compile error','GetFileName inspects a path string without opening the file.','GetExtension|GetDirectoryName'),
 S('// Assume notes.txt is writable.\nSystem.IO.File.~WriteAllText~("notes.txt","${word}");','Writes the text and closes the file','Only reads the file|Appends by default','WriteAllText creates or replaces the file content and closes the handle.','ReadAllText|AppendAllText','What happens to the file?')),
 L('records','Records and non-destructive updates','Records supply value equality for data models. with produces a copy with selected changes; reference-valued components still have shallow-copy behavior. Positional records generate properties and deconstruction. Record classes remain reference types despite their value equality.',
 S('var a=new Item(${n}); var b=a ~with~ {Count=${m}}; Console.WriteLine(a.Count);\nrecord Item(int Count);','${n}','${m}|Compile error','with creates another record; it leaves the original property unchanged.','new|as'),
 S('Console.WriteLine(new Item(${n}) ~==~ new Item(${n}));\nrecord Item(int Count);','True','False|Compile error','Record equality compares component values.','!=|is'),
 S('var item=new Item("${word}",${n}); var (name,count)=~item~; Console.WriteLine(name);\nrecord Item(string Name,int Count);','${word}','${n}|Compile error','The positional record provides Deconstruct for its components.','item.Name|item.Count'),
 S('var item=new Item(${n}); Console.WriteLine(item.~Count~);\nrecord Item(int Count);','${n}','0|Compile error','The positional component generates a property named Count.','count|Count()')),
 L('delegates','Delegates, captures, and events','Delegates are typed callable values. Func returns a result and Action returns void. Lambdas capture variables. Events let consumers subscribe while restricting who can invoke notifications. Remember to unsubscribe when publisher lifetime exceeds subscriber lifetime.',
 S('Func<int,int> f=x ~=>~ x+1; Console.WriteLine(f(${n}));','${next}','${n}|Compile error','The lambda matches a function from int to int.','->|:'),
 S('int n=${n}; Func<int> f=()=>n; n++; Console.WriteLine(~f()~);','${next}','${n}|Compile error','The closure reads the updated captured variable.','n-1|0'),
 S('Action f=()=>Console.WriteLine("${word}"); ~f()~;','${word}','No output|Compile error','Action represents a call with no returned value.','f.ToString()|f.GetHashCode()'),
 S('// Given an event Changed and a compatible handler:\npublisher.Changed ~+=~ handler;','Subscribes the handler','Invokes the event immediately|Removes the handler','+= attaches an event subscriber; the publisher controls invocation.','-=|=','What does this statement do?')),
 L('linq','LINQ and deferred enumeration','LINQ composes typed queries over sequences. Where filters, Select transforms, and materialization such as ToList forces evaluation. Deferred queries can observe source mutations made before enumeration. Query syntax is another surface for these operations.',
 S('Console.WriteLine(new[]{${n},0}.~Where~(x=>x>0).Count());','1','2|0','Where retains just the positive element.','Select|SkipWhile'),
 S('Console.WriteLine(new[]{"${word}"}.~Select~(x=>x.Length).Single());','${length}','0|Compile error','Select transforms a string into its length.','Where|OrderBy'),
 S('var a=new List<int>{${n}}; var q=a.Where(x=>x>0); a.Add(${m}); Console.WriteLine(q.~Count()~);','2','1|Compile error','Enumeration happens after Add, so the query sees both values.','First()|Last()'),
 S('var a=new List<int>{${n}}; var q=a.~ToList()~; a.Add(${m}); Console.WriteLine(q.Count);','1','2|Compile error','ToList materializes a separate list before the mutation.','AsEnumerable()|Where(x=>true)')),
 L('iterators','Yield and lazy producers','An iterator method yields values one at a time. yield return suspends production; yield break ends it. Re-enumerating normally creates a new traversal. Keep resource lifetimes and side effects in mind when a consumer stops early.',
 S('IEnumerable<int> Values(){~yield return~ ${n}; yield return ${m};} Console.WriteLine(Values().First());','${n}','${m}|Compile error','The first MoveNext produces the first yielded value.','return|yield break'),
 S('IEnumerable<int> Values(){yield return ${n}; ~yield break~;} Console.WriteLine(Values().Count());','1','0|Compile error','yield break terminates after the first value.','continue|break'),
 S('int calls=0; IEnumerable<int> Values(){calls++;yield return ${n};} var q=Values(); Console.WriteLine(~calls~);','0','1|Compile error','The iterator body has not executed because no enumeration began.','q.Count()|calls+1'),
 S('IEnumerable<int> Values(){yield return ${n};yield return ${m};} Console.WriteLine(Values().~Take(1)~.Count());','1','2|Compile error','Take limits consumption to the first element.','Skip(0)|ToList()')),
 L('generics','Constraints and generic APIs','Constraints specify which operations are valid for a type parameter. IComparable<T> supplies ordering, new() permits construction, and class or struct constrain representation categories. Prefer expressing a capability over duplicating an API for every concrete type.',
 S('T Identity<T>(~T x~)=>x; Console.WriteLine(Identity("${word}"));','${word}','Compile error|null','The type parameter connects input and output types.','object x|string x'),
 S('// Method declaration:\nT Make<T>() where T : ~new()~ => new T();','Requires a public parameterless constructor','Requires an interface only|Creates any abstract type','new() makes construction of T valid within the generic method.','class|notnull','What requirement permits new T()?'),
 S('// Method declaration:\nbool Equal<T>(T a,T b) => ~EqualityComparer<T>.Default.Equals(a,b)~;','Uses the default equality contract for T','Compares only memory addresses|Requires every T to be int','EqualityComparer<T>.Default supports typed equality without assuming an operator exists.','a==b|ReferenceEquals(a,b)','What equality behavior is requested?'),
 S('T First<T>(~IReadOnlyList<T> xs~)=>xs[0]; Console.WriteLine(First(new[]{"${word}"}));','${word}','Compile error|Empty string','The interface supports indexed reading while preserving the element type.','T xs|IEnumerable<T> xs')),
 L('async','Tasks and asynchronous control flow','Task<T> represents eventual completion with a value. await suspends an async method until completion; it does not inherently start a thread. Exceptions are observed when awaiting a failed task. Async methods should normally return Task rather than async void outside event handlers.',
 S('async Task<int> Next(){return ~await~ Task.FromResult(${n}+1);} Console.WriteLine(await Next());','${next}','${n}|Compile error','await extracts the task result within the async method.','yield|new'),
 S('var task=Task.FromResult("${word}"); Console.WriteLine(~await task~);','${word}','A task description|Compile error','Awaiting obtains the produced string.','task|task.IsCompleted'),
 S('try {await Task.~FromException~<int>(new Exception("${word}"));} catch(Exception e){Console.WriteLine(e.Message);}','${word}','No output|Compile error','Awaiting an exceptional task rethrows its failure at the await point.','FromResult|Run'),
 S('// Method declaration:\nasync ~Task<int>~ Read(){await Task.Yield();return ${n};}','An awaitable computation yielding an int','A synchronous int return|A fire-and-forget void method','Task<int> lets callers observe both completion and failure.','int|void','What contract does the return type expose?')),
 L('cancellation','Cancellation and coordinated completion','CancellationToken communicates cooperative cancellation. It does not forcibly stop a thread. Task.WhenAll joins several tasks; locks protect synchronous shared-state operations and cannot contain await. Test success, failure, and cancellation as separate outcomes.',
 S('using var cts=new CancellationTokenSource(); cts.~Cancel()~; Console.WriteLine(cts.Token.IsCancellationRequested);','True','False|Compile error','Cancel marks the token so participating operations can observe the request.','Dispose()|TryReset()'),
 S('var results=await Task.~WhenAll~(Task.FromResult(${n}),Task.FromResult(${m})); Console.WriteLine(results[0]);','${n}','${m}|Compile error','WhenAll returns results in input-task order, regardless of completion order.','WhenAny|Run'),
 S('using var cts=new CancellationTokenSource(); cts.Cancel(); try {cts.Token.~ThrowIfCancellationRequested()~;} catch(OperationCanceledException){Console.WriteLine("cancelled");}','cancelled','No output|Compile error','This explicit check turns a cancellation request into a cancellation exception.','ToString()|GetHashCode()'),
 S('object gate=new(); int n=${n}; ~lock~(gate){n++;} Console.WriteLine(n);','${next}','${n}|Compile error','lock protects the synchronous critical section and releases the monitor on exit.','using|await')),
 ]
